/* Paul's Letters, part 1: Romans – Colossians. Right answer first; the app shuffles. */

BQ.book({
  id: "romans",
  title: "Made Right with God by Faith",
  overview: "Romans is Paul's fullest explanation of the good news. He shows that everyone, Jew and Gentile, has sinned and fallen short of God's glory. But God makes people right with Himself as a free gift, through faith in Jesus, who died for us. Paul explains life in the Spirit, God's plan for Israel, and how believers should live: giving their whole lives to God, loving each other, and welcoming one another.",
  key: ["Romans 5:8", "God shows His love for us in this: while we were still sinners, Christ died for us."],
  cast: [
    ["Paul", "Person", "1:1", "An apostle who hadn't visited Rome yet. He wrote to prepare for his visit.", "Acts 28:14–16"],
    ["Abraham", "Person", "ch. 4", "Paul's main example: Abraham was counted righteous because he believed God."],
    ["Adam", "Person", "ch. 5", "Through one man sin came into the world. Through one man, Jesus, comes life."],
    ["Phoebe", "Person", "16:1–2", "A servant of the church in Cenchreae who probably carried the letter to Rome."],
    ["Priscilla and Aquila", "People", "16:3–5", "A married couple who risked their lives for Paul and hosted a church in their home.", "Acts 18:2–3"],
    ["Rome", "Place", "1:7", "The capital of the empire, where a church of Jews and Gentiles was meeting."]
  ],
  pray: "Take a slow breath. Romans says there is now no condemnation for those who are in Christ Jesus. Let that sink in, and thank God for His gift (Romans 8:1).",
  sections: [
    [1, 3, "Everyone Needs Grace", "All people, religious or not, have sinned and fall short of God's glory."],
    [4, 5, "Right by Faith", "Like Abraham, we're made right by trusting God, and we have peace with God through Jesus."],
    [6, 8, "Life in the Spirit", "Dead to sin, alive in Christ. No condemnation, and nothing can separate us from God's love."],
    [9, 11, "God and Israel", "God's faithfulness to Israel and His mercy to the nations."],
    [12, 16, "Living It Out", "Living sacrifices, love in action, respect for authority, and welcoming one another."]
  ],
  qs: [
    { r: 1, ref: "Romans 3:23", ch: [3], q: "Romans 3:23 says, “All have sinned and fall short of the ____ of God.”", o: ["glory", "law", "temple", "kingdom"], why: "Nobody measures up. That's why everyone needs the same good news." },
    { r: 1, ref: "Romans 6:23", ch: [6], q: "Romans 6:23 says the wages of sin is death. What is the gift of God?", o: ["Eternal life in Christ Jesus", "A long and easy life", "A brand new set of laws", "Riches in this world"], why: "Wages are earned. Gifts aren't. Eternal life is something God gives freely." },
    { r: 1, ref: "Romans 8:28", ch: [8], q: "Romans 8:28 says that in all things God works for the good of whom?", o: ["Those who love Him", "Everyone who is rich", "Only the apostles", "People who never fail"], why: "Not everything that happens is good, but God works in everything for the good of His people." },
    { r: 1, ref: "Romans 1:16", ch: [1], q: "True or false: Paul said he was ashamed of the gospel.", tf: false, why: "“I am not ashamed of the gospel, because it is the power of God that brings salvation to everyone who believes” (1:16)." },
    { r: 1, ref: "Romans 12:1", ch: [12], q: "Romans 12:1 urges believers to offer their bodies as what?", o: ["Living sacrifices", "Temple servants", "Soldiers for Rome", "Gifts to the poor"], why: "Not a dead animal on an altar, but your whole everyday life given to God. That's true worship." },
    { r: 2, ref: "Romans 5:8", ch: [5], q: "How does Romans 5:8 say God shows His love for us?", o: ["Christ died for us while we were still sinners", "He waits until we clean up our lives", "He only loves people who love Him first", "He gives good people what they deserve"], why: "God didn't wait for us to get better. He loved us at our worst." },
    { r: 2, ref: "Romans 8:1", ch: [8], q: "Romans 8:1 says there is now no what for those who are in Christ Jesus?", o: ["Condemnation", "Suffering", "Temptation", "Work"], why: "The verdict is in: not guilty. Believers still struggle, but they're no longer condemned." },
    { r: 2, ref: "Romans 4:1–3", ch: [4], q: "Why does Paul use Abraham as an example in Romans 4?", o: ["He was made right with God by believing", "He was the richest man of his time", "He built the very first temple", "He never once made a mistake"], why: "“Abraham believed God, and it was credited to him as righteousness” (4:3). Faith, not works." },
    { r: 2, ref: "Romans 12:2", ch: [12], q: "What does Romans 12:2 say about the pattern of this world?", o: ["Don't copy it; let God renew your mind", "Follow it closely so you fit in", "It doesn't really matter at all", "Only priests need to avoid it"], why: "God changes us from the inside out as He renews the way we think." },
    { r: 3, ref: "Romans 1:17 · Habakkuk 2:4", ch: [1], look: ["Habakkuk 2:4"], q: "Paul writes, “The righteous will live by faith.” Which prophet wrote that first?", o: ["Habakkuk", "Isaiah", "Jonah", "Malachi"], why: "Habakkuk 2:4. Paul builds his whole letter on it." },
    { r: 3, ref: "Romans 5:12–19 · Genesis 3", ch: [5], look: ["Genesis 3:1–19", "1 Corinthians 15:21–22"], q: "Romans 5 compares two men whose single act affected all humanity. Who are they?", o: ["Adam and Jesus", "Moses and Elijah", "Abraham and David", "Peter and Paul"], why: "Through Adam's disobedience came sin and death. Through Jesus' obedience comes righteousness and life." },
    { r: 3, ref: "Romans 10:9, 13 · Joel 2:32", ch: [10], look: ["Joel 2:32"], q: "Romans 10:9 says if you declare “Jesus is Lord” and believe God raised Him from the dead, what happens?", o: ["You will be saved", "You must still earn it", "You will become a priest", "You will never suffer"], why: "Paul backs it up with Joel 2:32: “Everyone who calls on the name of the Lord will be saved” (Romans 10:13)." }
  ],
  words: [
    ["Righteousness", "Romans 1:17", "Being right with God. Paul says God gives it as a gift through faith."],
    ["Justified", "Romans 5:1", "Declared not guilty and right with God, like a judge's verdict."],
    ["Grace", "Romans 3:24", "God's kindness that we don't earn and can't repay."],
    ["Flesh", "Romans 8:5", "Paul's word for the human nature that pulls away from God."],
    ["Gentile", "Romans 1:16", "Anyone who isn't Jewish. The gospel is for them too."]
  ],
  under: [
    ["Romans 5:8", "While we were still sinners.", "God's love came first, before we ever got our act together.", "When you feel unlovable this week, read this verse out loud."],
    ["Romans 8:1", "No condemnation.", "If you're in Christ, the guilty verdict has been lifted.", "Name one thing you still feel condemned about, and thank God it's covered."],
    ["Romans 8:28", "God works for the good.", "God can weave even painful things into something good for His people.", "Look back at a hard season and name one good thing God brought out of it."],
    ["Romans 12:2", "Be transformed.", "Real change starts in how you think.", "Replace one negative thought pattern this week with a truth from Scripture."]
  ],
  reflect: ["Paul says nothing in all creation can separate us from the love of God in Christ Jesus (Romans 8:38–39). What fear would shrink if you really believed that?", "Romans 8:31–39"],
  close: "Thank God that He loved you while you were still a sinner (5:8). Rest in the truth that there's no condemnation for you in Christ (8:1). And offer Him your whole life today as a living sacrifice (12:1)."
});

BQ.book({
  id: "1-corinthians",
  title: "Love Holds a Church Together",
  overview: "The church in Corinth was gifted but messy. They split into fan clubs around different leaders, tolerated sexual sin, sued each other, argued about food offered to idols, and showed off their spiritual gifts. Paul writes to correct them with both firmness and love. He reminds them the message of the cross looks foolish but is God's power, describes the church as one body, gives the great love chapter, and explains the resurrection.",
  key: ["1 Corinthians 13:13", "These three remain: faith, hope and love. But the greatest of these is love."],
  cast: [
    ["Paul", "Person", "throughout", "He started the church in Corinth and stayed there a year and a half.", "Acts 18:1–11"],
    ["Apollos", "Person", "chs. 1, 3", "A gifted teacher some Corinthians preferred over Paul. Paul said they were both just servants."],
    ["Chloe's household", "People", "1:11", "People who told Paul about the divisions in the church."],
    ["Cephas (Peter)", "Person", "1:12; 15:5", "Another leader some claimed to follow. The risen Jesus appeared to him."],
    ["Corinth", "Place", "1:2", "A busy, wealthy Greek port city known for its loose morals."]
  ],
  pray: "Take a slow breath. Paul says love is patient and kind. Ask God to fill you with that kind of love for the people closest to you (1 Corinthians 13:4).",
  sections: [
    [1, 4, "A Divided Church", "Factions around leaders, and the wisdom of the cross that looks foolish to the world."],
    [5, 7, "Bodies and Marriage", "Sexual sin, lawsuits, the body as God's temple, and marriage and singleness."],
    [8, 11, "Freedom and Worship", "Food offered to idols, giving up rights for others, and the Lord's Supper."],
    [12, 14, "Gifts and Love", "One body with many parts, love as the greatest way, and order in worship."],
    [15, 16, "Resurrection", "Christ is risen, and so will we be. Death has lost its sting."]
  ],
  qs: [
    { r: 1, ref: "1 Corinthians 1:10–13", ch: [1], q: "What problem had split the Corinthian church?", o: ["People took sides behind leaders", "They had no leaders of any kind", "They refused to meet together", "They argued about the calendar"], why: "“I follow Paul.” “I follow Apollos.” Paul asked them, “Is Christ divided?” (1:13)." },
    { r: 1, ref: "1 Corinthians 13:4", ch: [13], art: "heart", q: "1 Corinthians 13:4 begins, “Love is ____, love is kind.”", o: ["patient", "strong", "powerful", "loud"], why: "The famous love chapter was written to a church that was fighting. Love isn't just a feeling; it's how we treat each other." },
    { r: 1, ref: "1 Corinthians 12:12, 27", ch: [12], q: "What picture does Paul use for the church in chapter 12?", o: ["A body with many parts", "A city with many walls", "A ship with many sailors", "A tree with many roots"], why: "Every part matters. The eye can't say to the hand, “I don't need you!” (12:21)." },
    { r: 1, ref: "1 Corinthians 15:3–6", ch: [15], q: "True or false: Paul says the risen Jesus appeared to more than five hundred people at one time.", tf: true, why: "Most of them were still alive when Paul wrote, so readers could go and ask them (15:6)." },
    { r: 1, ref: "1 Corinthians 6:19–20", ch: [6], q: "What does Paul call a believer's body in 1 Corinthians 6:19?", o: ["A temple of the Holy Spirit", "A prison for the soul", "A tool for pleasure", "Something that doesn't matter"], why: "“You are not your own; you were bought at a price. Therefore honor God with your bodies” (6:19–20)." },
    { r: 2, ref: "1 Corinthians 1:18", ch: [1], art: "cross", q: "How does Paul say the message of the cross looks to people who are perishing?", o: ["Like foolishness", "Like great wisdom", "Like a good story", "Like a new law"], why: "A crucified Savior sounded ridiculous to Greeks and offensive to Jews. But to those being saved, it's the power of God." },
    { r: 2, ref: "1 Corinthians 13:1–3", ch: [13], q: "What does Paul say spiritual gifts are worth without love?", o: ["Nothing", "Twice as much", "About half", "Everything"], why: "Without love, even speaking in tongues is just a noisy gong. Love gives everything else its value." },
    { r: 2, ref: "1 Corinthians 10:13", ch: [10], q: "What does 1 Corinthians 10:13 promise about temptation?", o: ["God will provide a way out so you can stand", "You will never be tempted again", "Temptation is always too strong to resist", "Only weak people get tempted"], why: "God is faithful. He won't let you be tempted beyond what you can bear." },
    { r: 2, ref: "1 Corinthians 15:55–57", ch: [15], q: "Because Jesus rose, what does Paul ask death in 15:55?", o: ["Where is your sting?", "Why are you so strong?", "When will you come?", "Who sent you?"], why: "Death has lost its power over believers. “Thanks be to God! He gives us the victory through our Lord Jesus Christ” (15:57)." },
    { r: 3, ref: "1 Corinthians 11:23–26 · Luke 22:19–20", ch: [11], look: ["Luke 22:19–20"], art: "bread", q: "Paul passes on Jesus' words at the Last Supper, “Do this in remembrance of me.” Which other book records almost the same words?", o: ["Luke", "John", "Acts", "Revelation"], why: "Paul and Luke traveled together, and their wording of the Last Supper is almost identical." },
    { r: 3, ref: "1 Corinthians 15:45 · Genesis 2:7", ch: [15], look: ["Genesis 2:7", "Romans 5:12–19"], q: "Paul calls Jesus “the last Adam.” What does that mean?", o: ["Jesus brings life where Adam brought death", "Jesus was a direct son of Adam", "Jesus once lived in the garden of Eden", "Adam and Jesus were the same person"], why: "The first Adam became a living being; the last Adam became a life-giving spirit (15:45)." },
    { r: 3, ref: "1 Corinthians 5:7 · Exodus 12:21", ch: [5], look: ["Exodus 12:21–23"], q: "Paul writes, “Christ, our Passover lamb, has been sacrificed.” Which Old Testament event is he pointing to?", o: ["The first Passover in Egypt", "The flood in Noah's day", "The fall of Jericho", "The building of Solomon's temple"], why: "The lamb's blood saved Israel's firstborn. Jesus' blood saves His people (Exodus 12)." }
  ],
  words: [
    ["Factions", "1 Corinthians 1:10", "Groups that split off and compete with each other."],
    ["Spiritual gifts", "1 Corinthians 12:4", "Abilities the Holy Spirit gives believers to help the church."],
    ["Resurrection", "1 Corinthians 15:12", "Rising from the dead with a new, glorious body, as Jesus did."],
    ["Edify", "1 Corinthians 14:12", "To build up. Gifts are for building others up, not showing off."],
    ["Firstfruits", "1 Corinthians 15:20", "The first part of the harvest. Jesus' resurrection is the first, and it promises ours."]
  ],
  under: [
    ["1 Corinthians 10:13", "God will provide a way out.", "No temptation is bigger than God's faithfulness.", "Next time you're tempted, stop and look for the way out God promised."],
    ["1 Corinthians 13:4–5", "Love is patient, love is kind.", "Real love shows up in small, everyday choices.", "Put your name in place of “love” in these verses, and pick one line to work on."],
    ["1 Corinthians 15:58", "Your labor is not in vain.", "Because Jesus rose, nothing you do for Him is wasted.", "Keep going this week on something good you've been tempted to quit."],
    ["1 Corinthians 16:14", "Do everything in love.", "Love is meant to be the motive behind everything.", "Before a task this week, ask: how can I do this in love?"]
  ],
  reflect: ["The Corinthians had amazing gifts but were missing love (1 Corinthians 13:1–3). Where in your life might you be doing good things without love?", "1 Corinthians 13:1–7"],
  close: "Thank God that the foolish-looking cross is His power to save (1:18). Ask Him to make your love patient and kind (13:4). And thank Jesus that because He rose, death has lost its sting (15:55)."
});

BQ.book({
  id: "2-corinthians",
  title: "Strength in Weakness",
  overview: "This is Paul's most personal letter. Some in Corinth were following flashy “super-apostles” and mocking Paul for being weak and unimpressive. Paul answers by opening up about his sufferings: beatings, shipwrecks, sleepless nights and a painful “thorn in the flesh.” He shows that God's power works best through weakness. He also writes about comfort in trouble, being a new creation, and generous giving.",
  key: ["2 Corinthians 12:9", "My grace is all you need, because My power is made perfect in weakness."],
  cast: [
    ["Paul", "Person", "throughout", "Opens his heart about his sufferings, his weaknesses and his love for the church."],
    ["Titus", "Person", "chs. 2, 7–8", "Paul's coworker who brought good news from Corinth and helped organize the offering."],
    ["The “super-apostles”", "People", "chs. 10–12", "Impressive-looking teachers who bragged about themselves and led people away."],
    ["The Macedonian churches", "People", "8:1–5", "Poor churches who gave generously, even beyond what they could afford."],
    ["Corinth", "Place", "1:1", "The church Paul had started and kept loving, even when it hurt him."]
  ],
  pray: "Take a slow breath. Paul learned that God's grace is enough, especially when we feel weak. Bring God your weakest area today and ask for His strength there (2 Corinthians 12:9).",
  sections: [
    [1, 7, "Comfort and Ministry", "God comforts us in trouble, treasure in jars of clay, and a new creation."],
    [8, 9, "Generous Giving", "The collection for poor believers in Jerusalem. God loves a cheerful giver."],
    [10, 13, "Strength in Weakness", "Paul answers his critics, lists his sufferings, and shares his thorn in the flesh."]
  ],
  qs: [
    { r: 1, ref: "2 Corinthians 1:3–4", ch: [1], q: "Why does Paul say God comforts us in our troubles?", o: ["So we can comfort others too", "So we never have trouble again", "So we can brag about it", "So we don't need friends"], why: "Your hard seasons can become a gift to someone else going through the same thing." },
    { r: 1, ref: "2 Corinthians 4:7", ch: [4], art: "jar", q: "Paul says we have this treasure in what?", o: ["Jars of clay", "Chests of gold", "Temple vaults", "Royal palaces"], why: "Ordinary, breakable people carry the treasure of the gospel, so it's clear the power comes from God." },
    { r: 1, ref: "2 Corinthians 5:17", ch: [5], q: "2 Corinthians 5:17: “If anyone is in Christ, the new ____ has come.”", o: ["creation", "law", "temple", "king"], why: "The old has gone. Being in Christ isn't a small improvement; it's a whole new start." },
    { r: 1, ref: "2 Corinthians 12:7–9", ch: [12], q: "True or false: When Paul prayed three times for his “thorn in the flesh” to go away, God took it away.", tf: false, why: "God said, “My grace is sufficient for you, for my power is made perfect in weakness” (12:9). Sometimes the answer is grace, not removal." },
    { r: 1, ref: "2 Corinthians 9:7", ch: [9], q: "What kind of giver does God love, according to 2 Corinthians 9:7?", o: ["A cheerful giver", "A rich giver", "A secret giver", "A frequent giver"], why: "Not out of guilt or pressure. Give what you've decided in your heart, and do it gladly." },
    { r: 2, ref: "2 Corinthians 11:24–30", ch: [11], q: "When his critics bragged about themselves, what did Paul boast about instead?", o: ["His sufferings and weaknesses", "His wealth and family", "His perfect speeches", "His many followers"], why: "Beaten, stoned, shipwrecked, hungry and cold. Paul boasted in the things that showed God's power, not his own." },
    { r: 2, ref: "2 Corinthians 5:20", ch: [5], q: "What does Paul call believers in 2 Corinthians 5:20?", o: ["Christ's ambassadors", "God's soldiers", "Heaven's judges", "The world's teachers"], why: "An ambassador represents their king. God makes His appeal to the world through us: be reconciled to God." },
    { r: 2, ref: "2 Corinthians 4:17–18", ch: [4], q: "How could Paul call his troubles “light and momentary”?", o: ["He compared them with eternal glory", "His troubles really were easy ones", "He couldn't feel any pain at all", "He was only exaggerating a little"], why: "Next to the weight of eternal glory, even heavy trouble is light. Fix your eyes on what's unseen and eternal." },
    { r: 2, ref: "2 Corinthians 8:9", ch: [8], q: "2 Corinthians 8:9 says Jesus was rich but became poor. Why?", o: ["So we could become rich through Him", "Because He lost all His money", "To teach us all to stay poor", "Because the temple took His wealth"], why: "He gave up heaven's glory to give us every spiritual blessing. That's the reason for generous giving." },
    { r: 3, ref: "2 Corinthians 3:7–18 · Exodus 34:29–35", ch: [3], look: ["Exodus 34:29–35"], q: "Paul mentions Moses covering his shining face with a veil. What happens when someone turns to the Lord?", o: ["The veil is taken away", "Their face starts to glow", "They must wear a veil", "They see Moses"], why: "In Christ we see God's glory clearly and are changed into His likeness, more and more (3:16–18)." },
    { r: 3, ref: "2 Corinthians 5:21 · Isaiah 53:5–6", ch: [5], look: ["Isaiah 53:5–6"], art: "cross", q: "2 Corinthians 5:21 says God made Him who had no sin to be sin for us. What does that mean?", o: ["He took our sin; we get His righteousness", "Jesus was secretly sinful all along", "Sin doesn't really matter anymore", "We still have to pay for our own sin"], why: "The great exchange: our sin on Him, His righteousness to us. Isaiah 53 saw it coming." },
    { r: 3, ref: "2 Corinthians 12:9 · Judges 7:2", ch: [12], look: ["Judges 7:2", "1 Corinthians 1:27"], q: "God's power is made perfect in weakness. Which Old Testament story shows God shrinking an army so no one could boast?", o: ["Gideon's 300 men", "David's mighty men", "Joshua at Jericho", "Saul's army"], why: "God cut Gideon's army from 32,000 to 300 so Israel would know the victory was His (Judges 7:2)." }
  ],
  words: [
    ["Comfort", "2 Corinthians 1:4", "Strength and encouragement that comes alongside you in pain."],
    ["Jars of clay", "2 Corinthians 4:7", "Cheap, breakable pots. A picture of ordinary people carrying God's treasure."],
    ["Reconcile", "2 Corinthians 5:18", "To bring back together people who were separated. To make peace."],
    ["Ambassador", "2 Corinthians 5:20", "Someone who represents their king or country in a foreign place."],
    ["Thorn in the flesh", "2 Corinthians 12:7", "Some ongoing pain or problem Paul had. We don't know exactly what it was."]
  ],
  under: [
    ["2 Corinthians 1:4", "Comfort others.", "God doesn't waste your pain. He can use it to help others.", "Reach out to someone going through something you've been through."],
    ["2 Corinthians 5:17", "The new has come.", "In Christ, you're not just improved. You're new.", "When old shame shows up this week, remind yourself: the old is gone."],
    ["2 Corinthians 9:7", "God loves a cheerful giver.", "Generosity flows best from a glad heart.", "Give something this week, and do it with a smile."],
    ["2 Corinthians 12:9", "My grace is sufficient.", "God's strength shows up most where we're weakest.", "Name your “thorn” and thank God for His grace in it."]
  ],
  reflect: ["Paul begged God three times to take away his thorn, and God answered with grace instead (2 Corinthians 12:7–9). Is there a weakness you've asked God to remove that He might want to show His strength through?", "2 Corinthians 12:7–10"],
  close: "Thank God that He comforts you so you can comfort others (1:4). Celebrate that you're a new creation in Christ (5:17). And lean on His grace, which is enough for your weakest places (12:9)."
});

BQ.book({
  id: "galatians",
  title: "Free in Christ",
  overview: "Paul started churches in Galatia. Then some teachers came in and told the Gentile believers they had to be circumcised and keep the law of Moses to really belong. Paul is furious, because that's a different gospel. He tells his own story and argues that people are made right with God by faith in Christ, not by keeping the law. Christ has set us free, so don't go back to slavery. Live by the Spirit, and you'll bear the Spirit's fruit.",
  key: ["Galatians 2:20", "I have been crucified with Christ. I no longer live, but Christ lives in me. The life I live now, I live by faith in the Son of God, who loved me and gave Himself for me."],
  cast: [
    ["Paul", "Person", "throughout", "A former persecutor who met Jesus and was sent to the Gentiles.", "Acts 9:1–19"],
    ["Peter (Cephas)", "Person", "ch. 2", "Paul corrected him to his face for pulling away from eating with Gentiles."],
    ["Barnabas", "Person", "ch. 2", "Paul's partner, who was also briefly led astray."],
    ["The troublemakers", "People", "1:7; 5:12", "Teachers who said Gentiles had to keep the law of Moses to be saved."],
    ["Abraham", "Person", "ch. 3", "Paul's example: Abraham believed God, and it was counted as righteousness.", "Genesis 15:6"],
    ["Galatia", "Place", "1:2", "A region in what is now Turkey, where Paul had started churches."]
  ],
  pray: "Take a slow breath. Galatians says it is for freedom that Christ has set us free. Ask God to show you any way you've been trying to earn His love (Galatians 5:1).",
  sections: [
    [1, 2, "Paul's Story", "There's only one gospel. Paul tells how he received it from Jesus, and how he confronted Peter."],
    [3, 4, "Faith, Not Law", "Abraham was made right by faith. The law was a guardian until Christ came. We're children, not slaves."],
    [5, 6, "Free to Love", "Stand firm in freedom, walk by the Spirit, bear His fruit, and carry each other's burdens."]
  ],
  qs: [
    { r: 1, ref: "Galatians 1:6–7", ch: [1], q: "Why was Paul so upset with the Galatians?", o: ["They were turning to another gospel", "They had stopped meeting together", "They were giving away too much", "They had stopped praying for him"], why: "Someone was adding rules to grace. Paul said that's not good news at all." },
    { r: 1, ref: "Galatians 2:11–13", ch: [2], q: "Why did Paul confront Peter to his face in Antioch?", o: ["He stopped eating with Gentiles", "He refused to preach anymore", "He took money from the church", "He quit the church and went home"], why: "Peter pulled back out of fear of what others would think, and it sent the message that Gentile believers were second-class." },
    { r: 1, ref: "Galatians 5:22–23", ch: [5], q: "Which of these is part of the fruit of the Spirit?", o: ["Self-control", "Fame", "Wealth", "Power"], why: "Love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control." },
    { r: 1, ref: "Galatians 3:28", ch: [3], q: "True or false: Galatians 3:28 says that in Christ there is neither Jew nor Gentile, slave nor free, male nor female.", tf: true, why: "“You are all one in Christ Jesus.” Our differences remain, but they don't divide us in God's family." },
    { r: 1, ref: "Galatians 6:2", ch: [6], q: "Galatians 6:2 tells believers to carry each other's what?", o: ["Burdens", "Money", "Sins", "Secrets"], why: "“In this way you will fulfill the law of Christ.” Love shares the load." },
    { r: 2, ref: "Galatians 2:16", ch: [2], q: "According to Galatians 2:16, how is a person made right with God?", o: ["By faith in Jesus Christ", "By keeping the law of Moses", "By being circumcised", "By doing more good than bad"], why: "Paul says it three times in one verse: not by the works of the law, but by faith in Christ." },
    { r: 2, ref: "Galatians 5:1", ch: [5], q: "What does Galatians 5:1 say Christ has set us free for?", o: ["Freedom", "Rules", "Wealth", "Fame"], why: "“Stand firm, then, and do not let yourselves be burdened again by a yoke of slavery.”" },
    { r: 2, ref: "Galatians 5:13", ch: [5], q: "How does Paul say believers should use their freedom?", o: ["To serve one another humbly in love", "To do whatever they feel like", "To keep away from other Christians", "To ignore all of God's commands"], why: "Freedom isn't permission to sin. It's freedom to love." },
    { r: 2, ref: "Galatians 6:7–9", ch: [6], q: "“A man reaps what he sows.” What is Galatians 6:7–8 warning about?", o: ["Our choices have real results", "Farmers should always plant early", "God can easily be fooled", "Nothing we do really matters"], why: "Sow to please the Spirit, and you'll reap eternal life. So don't give up doing good (6:9)." },
    { r: 3, ref: "Galatians 3:6 · Genesis 15:6", ch: [3], look: ["Genesis 15:6"], q: "Paul says Abraham “believed God, and it was credited to him as righteousness.” Where in Genesis is that?", o: ["Genesis 15:6", "Genesis 1:1", "Genesis 50:20", "Genesis 3:15"], why: "Abraham was declared right with God by faith, long before the law of Moses or circumcision." },
    { r: 3, ref: "Galatians 4:4–5", ch: [4], look: ["Luke 2:21–24"], q: "Galatians 4:4 says when the set time had fully come, God sent His Son, born under the law. Why?", o: ["To buy us back and adopt us", "To start a brand new religion", "To replace all the prophets", "To become the king of Rome"], why: "Jesus came at just the right moment to redeem us and make us part of God's family (4:5)." },
    { r: 3, ref: "Galatians 5:22–23 · John 15:5", ch: [5], look: ["John 15:4–5"], art: "vine", q: "Paul calls love, joy and peace the “fruit” of the Spirit. What did Jesus say about bearing fruit?", o: ["Stay connected to Him, the vine", "Try harder and work longer", "Fruit grows only in Israel", "Only apostles can bear fruit"], why: "Fruit grows naturally on branches connected to the vine. The Spirit produces it as we stay close to Jesus." }
  ],
  words: [
    ["Gospel", "Galatians 1:6", "The good news that Jesus saves us by grace through faith."],
    ["Circumcision", "Galatians 5:2", "A sign of God's covenant with Abraham. Some said Gentiles needed it to be saved."],
    ["Justified", "Galatians 2:16", "Declared right with God. Not guilty."],
    ["Yoke", "Galatians 5:1", "A heavy wooden harness. Paul uses it for the burden of trying to earn salvation."],
    ["Fruit of the Spirit", "Galatians 5:22", "The character the Holy Spirit grows in believers."]
  ],
  under: [
    ["Galatians 2:20", "Christ lives in me.", "Your old self was crucified with Christ. Now He lives through you.", "Before a hard moment this week, pray: “Jesus, live through me here.”"],
    ["Galatians 5:1", "Christ has set us free.", "You don't have to earn God's love. Stop trying.", "Name one way you've been trying to earn God's approval, and let it go."],
    ["Galatians 5:22–23", "The fruit of the Spirit.", "God grows good character in you as you walk with His Spirit.", "Pick one fruit and ask the Spirit to grow it in you this week."],
    ["Galatians 6:9", "Don't grow weary in doing good.", "The harvest comes, even if it's slow.", "Keep going on one good thing you're tired of doing."]
  ],
  reflect: ["The Galatians started with grace but were drifting into trying to earn God's love by keeping rules (Galatians 3:3). Where are you tempted to measure your standing with God by how well you perform?", "Galatians 3:1–5"],
  close: "Thank Jesus that He loved you and gave Himself for you (2:20). Stand firm in the freedom He's given you (5:1). And ask the Spirit to grow His fruit in your life (5:22–23)."
});

BQ.book({
  id: "ephesians",
  title: "One New Family in Christ",
  overview: "Paul wrote Ephesians from prison. The first half is about what God has done: chosen us, adopted us, forgiven us, and made us alive in Christ by grace. He's torn down the wall between Jews and Gentiles to make one new family. The second half is about how to live because of that: in unity, love and light, at home and at work. It ends with the armor of God, so we can stand firm.",
  key: ["Ephesians 2:8–9", "It's by grace you have been saved, through faith. It isn't from yourselves; it's the gift of God. Not by works, so no one can boast."],
  cast: [
    ["Paul", "Person", "3:1; 6:20", "Writing as a “prisoner for the Lord,” still praying big prayers for the church."],
    ["Tychicus", "Person", "6:21", "A dear brother and faithful servant who carried the letter."],
    ["The believers in Ephesus", "People", "1:1", "Christians in a big city famous for its temple to the goddess Artemis.", "Acts 19:23–27"],
    ["Jews and Gentiles", "People", "ch. 2", "Once divided by a wall of hostility, now one new people in Christ."],
    ["Ephesus", "Place", "1:1", "A major city in Asia where Paul spent about three years.", "Acts 20:31"]
  ],
  pray: "Take a slow breath. Paul prayed that believers would grasp how wide, long, high and deep Christ's love is. Ask God to help you feel that love today (Ephesians 3:17–19).",
  sections: [
    [1, 3, "What God Has Done", "Every spiritual blessing, saved by grace, one new family, and a prayer to know Christ's love."],
    [4, 6, "How to Live", "Unity, a new self, walking in love and light, home and work, and the armor of God."]
  ],
  qs: [
    { r: 1, ref: "Ephesians 2:8–9", ch: [2], q: "Ephesians 2:8 says we have been saved by grace through what?", o: ["Faith", "Works", "Sacrifices", "The law"], why: "“...and this is not from yourselves, it is the gift of God, not by works, so that no one can boast.”" },
    { r: 1, ref: "Ephesians 6:11", ch: [6], q: "What does Paul tell believers to put on so they can stand against the devil's schemes?", o: ["The full armor of God", "A crown of pure gold", "A priest's linen robe", "Rough sackcloth and ashes"], why: "The belt of truth, the breastplate of righteousness, the shield of faith, the helmet of salvation and the sword of the Spirit." },
    { r: 1, ref: "Ephesians 6:17", ch: [6], q: "In the armor of God, what is the sword of the Spirit?", o: ["The word of God", "Prayer", "Faith", "Salvation"], why: "It's the only weapon for attack in the armor. Jesus fought temptation with Scripture too (Matthew 4)." },
    { r: 1, ref: "Ephesians 2:14", ch: [2], q: "True or false: Paul says Jews and Gentiles should stay in separate churches.", tf: false, why: "The opposite: Christ destroyed the dividing wall of hostility and made the two groups one (2:14)." },
    { r: 1, ref: "Ephesians 3:1; 4:1", ch: [3, 4], q: "Where was Paul when he wrote Ephesians?", o: ["In prison", "On a ship", "In the temple", "At home in Tarsus"], why: "He calls himself a prisoner for the Lord. Even in chains, he was praying and writing for others." },
    { r: 2, ref: "Ephesians 2:10", ch: [2], q: "Ephesians 2:10 says we are God's handiwork, created in Christ Jesus to do what?", o: ["Good works God prepared for us", "Earn our own salvation", "Rule over other people", "Stay away from the world"], why: "We aren't saved by good works, but we are saved for them. God planned them ahead of time." },
    { r: 2, ref: "Ephesians 4:26–27", ch: [4], q: "What does Ephesians 4:26 say about anger?", o: ["Deal with it before the sun goes down", "Every kind of anger is a sin", "Never show your feelings at all", "Get even before the sun sets"], why: "“In your anger do not sin.” Deal with it quickly, before it gives the devil a foothold (4:27)." },
    { r: 2, ref: "Ephesians 4:32", ch: [4], q: "Ephesians 4:32 says to forgive each other just as what?", o: ["God forgave you in Christ", "They forgive you first", "The law requires", "You feel like it"], why: "We forgive because we've been forgiven. That's the measure." },
    { r: 2, ref: "Ephesians 6:12", ch: [6], q: "Who does Paul say our real struggle is against?", o: ["Spiritual forces of evil", "Our difficult neighbors", "The Roman government", "Other churches in town"], why: "People aren't the real enemy. There's a spiritual battle going on behind the scenes." },
    { r: 3, ref: "Ephesians 5:31–32 · Genesis 2:24", ch: [5], look: ["Genesis 2:24"], q: "Paul quotes, “A man will leave his father and mother and be united to his wife.” Where was that first written?", o: ["Genesis 2", "Exodus 20", "Psalm 23", "Proverbs 31"], why: "Paul says marriage, from the very beginning, was a picture of Christ and the church (5:32)." },
    { r: 3, ref: "Ephesians 2:19–22 · 1 Peter 2:5", ch: [2], look: ["1 Peter 2:4–5"], art: "temple", q: "Paul says believers are being built together into a holy temple. What does that mean?", o: ["God lives among His people, the church", "Christians must build a new temple", "The Jerusalem temple will be rebuilt", "Churches must be made of stone"], why: "God's presence isn't limited to a building anymore. His people, together, are where He lives." },
    { r: 3, ref: "Ephesians 6:14–17 · Isaiah 59:17", ch: [6], look: ["Isaiah 59:17"], q: "The breastplate of righteousness and the helmet of salvation first appear in which prophet, worn by God Himself?", o: ["Isaiah", "Jonah", "Amos", "Haggai"], why: "In Isaiah 59:17 God puts on this armor to rescue His people. Paul says He now gives it to us." }
  ],
  words: [
    ["Grace", "Ephesians 2:8", "God's undeserved kindness. You can't earn it."],
    ["Adoption", "Ephesians 1:5", "Being made part of a family. God adopts believers as His children."],
    ["Redemption", "Ephesians 1:7", "Being bought back and set free, through Jesus' blood."],
    ["Unity", "Ephesians 4:3", "Being one, together, in peace. Paul urges believers to protect it."],
    ["Armor of God", "Ephesians 6:11", "God's protection for spiritual battles: truth, righteousness, peace, faith, salvation and Scripture."]
  ],
  under: [
    ["Ephesians 2:8", "By grace you have been saved.", "Salvation is a gift, not a paycheck.", "Thank God for one thing in your life you know you didn't earn."],
    ["Ephesians 3:20", "Immeasurably more than all we ask.", "God can do far more than you can imagine.", "Ask God for something big this week, and leave room for Him to surprise you."],
    ["Ephesians 4:32", "Forgiving each other.", "We forgive others because God forgave us first.", "Forgive someone this week, even if they never ask."],
    ["Ephesians 6:10", "Be strong in the Lord.", "Your strength for spiritual battles comes from God, not from you.", "Each morning this week, pray through one piece of the armor of God."]
  ],
  reflect: ["Paul prayed believers would grasp “how wide and long and high and deep” Christ's love is (Ephesians 3:18). Which part of God's love is hardest for you to believe is really for you?", "Ephesians 3:14–21"],
  close: "Thank God that you're saved by grace, as a gift (2:8). Ask Him to help you forgive the way you've been forgiven (4:32). And put on His armor so you can stand firm today (6:11)."
});

BQ.book({
  id: "philippians",
  title: "Joy That Doesn't Quit",
  overview: "Paul wrote this warm thank-you letter from prison to the church in Philippi, one of his favorite churches. Even in chains, he talks about joy again and again. He says to live is Christ and to die is gain, urges them to have the same humble attitude as Jesus, who gave up everything, and tells them not to worry about anything but to pray about everything. He has learned to be content in every situation through Christ, who gives him strength.",
  key: ["Philippians 4:4", "Rejoice in the Lord always. I'll say it again: Rejoice!"],
  cast: [
    ["Paul", "Person", "throughout", "Writing from prison, yet full of joy and thanks."],
    ["Timothy", "Person", "1:1; 2:19–22", "Paul's spiritual son, who truly cared about the Philippians."],
    ["Epaphroditus", "Person", "2:25–30; 4:18", "Brought the church's gift to Paul, got very sick, and nearly died serving."],
    ["Euodia and Syntyche", "People", "4:2–3", "Two women in the church Paul urged to agree with each other in the Lord."],
    ["Lydia and the jailer", "People", "Acts 16", "Some of the very first believers in Philippi, when the church began.", "Acts 16:14–34"],
    ["Philippi", "Place", "1:1", "A Roman colony in Macedonia, the first church Paul started in Europe."]
  ],
  pray: "Take a slow breath. Paul says don't be anxious about anything, but pray about everything with thanks. Tell God what's worrying you right now, and thank Him for one thing (Philippians 4:6–7).",
  sections: [
    [1, 1, "To Live Is Christ", "Paul's chains have spread the gospel. To live is Christ and to die is gain."],
    [2, 2, "The Mind of Christ", "Be humble like Jesus, who emptied Himself and became a servant, all the way to death."],
    [3, 3, "Pressing On", "Everything is loss compared to knowing Christ. Press on toward the goal."],
    [4, 4, "Rejoice Always", "Don't worry; pray. Think about what's good. Content in every situation."]
  ],
  qs: [
    { r: 1, ref: "Philippians 1:12–14", ch: [1], q: "Where was Paul when he wrote Philippians?", o: ["In chains, in prison", "On a ship to Spain", "In the temple", "At home with friends"], why: "Even the whole palace guard had heard about Christ because of Paul's chains (1:13)." },
    { r: 1, ref: "Philippians 4:4", ch: [4], q: "Philippians 4:4 says, “____ in the Lord always.”", o: ["Rejoice", "Rest", "Hide", "Work"], why: "Paul wrote this from prison. Joy in the Lord doesn't depend on circumstances." },
    { r: 1, ref: "Philippians 4:13", ch: [4], q: "Philippians 4:13: “I can do all this through him who gives me ____.”", o: ["strength", "money", "friends", "wisdom"], why: "In context, Paul means he can be content with plenty or with little, because Christ strengthens him (4:11–13)." },
    { r: 1, ref: "Philippians 4:6–7", ch: [4], q: "True or false: Paul says not to be anxious about anything, but to pray about everything with thanksgiving.", tf: true, why: "And then “the peace of God, which transcends all understanding, will guard your hearts and your minds” (4:7)." },
    { r: 1, ref: "Philippians 1:21", ch: [1], q: "Philippians 1:21: “For to me, to live is Christ and to die is ____.”", o: ["gain", "loss", "sad", "rest"], why: "If he lived, he'd serve Christ. If he died, he'd be with Christ. Either way, he won." },
    { r: 2, ref: "Philippians 2:5–8", ch: [2], q: "What attitude of Jesus does Philippians 2 tell us to have?", o: ["Humble, making Himself a servant", "Pride in His power and position", "Fear of what people might think", "Anger at those who rejected Him"], why: "Though He was God, Jesus took the form of a servant and obeyed all the way to death on a cross." },
    { r: 2, ref: "Philippians 3:7–8", ch: [3], q: "What did Paul say about all his achievements compared to knowing Christ?", o: ["He counted them as loss, even garbage", "They were worth more than anything", "They had earned his salvation", "He was proud of every single one"], why: "Paul had an impressive religious résumé, but he'd trade it all in a heartbeat for Jesus." },
    { r: 2, ref: "Philippians 4:11–12", ch: [4], q: "What secret did Paul say he had learned?", o: ["Being content in every situation", "How to get rich very quickly", "How to avoid every hardship", "How to please everybody"], why: "Hungry or full, poor or with plenty, he had learned contentment through Christ." },
    { r: 2, ref: "Philippians 4:8", ch: [4], q: "Philippians 4:8 tells us to think about whatever is what?", o: ["True, noble, right, pure, lovely", "Popular, trendy and exciting", "Scary, so we stay alert", "Wrong with other people"], why: "What you fill your mind with shapes your peace. Choose good things to dwell on." },
    { r: 3, ref: "Philippians 2:10–11 · Isaiah 45:23", ch: [2], look: ["Isaiah 45:22–23"], q: "Paul says every knee will bow and every tongue confess that Jesus is Lord. In Isaiah 45:23, who says every knee will bow to Him?", o: ["The Lord God Himself", "Cyrus, king of Persia", "Moses, the lawgiver", "Isaiah, the prophet"], why: "Paul applies to Jesus the words God spoke about Himself. That's a bold way of saying Jesus is God." },
    { r: 3, ref: "Philippians 1:13 · Acts 16:22–26", ch: [1], look: ["Acts 16:22–34"], q: "Paul's first visit to Philippi also involved chains. What happened that night in the Philippian jail?", o: ["An earthquake hit, and the jailer believed", "Paul escaped and never came back", "The guards let Paul go for a bribe", "Paul was sent straight to Rome"], why: "Paul and Silas sang hymns at midnight. The jailer's whole family became part of the first church in Philippi." },
    { r: 3, ref: "Philippians 3:20–21 · 1 Corinthians 15:51–53", ch: [3], look: ["1 Corinthians 15:51–53"], q: "Paul says our citizenship is in heaven and Jesus will transform our lowly bodies. Into what?", o: ["Bodies like His glorious body", "Angels with wings", "Spirits without bodies", "Younger versions of ourselves"], why: "Resurrection isn't escaping the body. It's getting a new, glorious one, like Jesus' risen body." }
  ],
  words: [
    ["Rejoice", "Philippians 4:4", "To be glad and celebrate. Paul talks about joy over and over in these four short chapters."],
    ["Content", "Philippians 4:11", "At peace with what you have, not always needing more."],
    ["Citizenship", "Philippians 3:20", "Where you belong. Philippi was proud to be Roman; believers belong to heaven."],
    ["Emptied", "Philippians 2:7", "Jesus set aside His rights and glory to become a servant."],
    ["Partnership", "Philippians 1:5", "Sharing in the work together. The Philippians shared in Paul's work by giving and praying."]
  ],
  under: [
    ["Philippians 1:6", "He will carry it on to completion.", "God finishes what He starts in you.", "When you feel like a work in progress, thank God He isn't done yet."],
    ["Philippians 2:3–4", "Value others above yourselves.", "Humility means looking out for others' interests, not just your own.", "Ask one person this week how you can help them, and do it."],
    ["Philippians 4:6–7", "Do not be anxious about anything.", "Prayer with thanksgiving trades anxiety for God's peace.", "Every time you feel anxious this week, turn it into a prayer and add one thank-you."],
    ["Philippians 4:13", "Through Him who gives me strength.", "Christ's strength is enough for whatever situation you're in.", "Face one hard situation this week by praying this verse first."]
  ],
  reflect: ["Paul found joy in prison and learned to be content in every situation (Philippians 4:11–13). What circumstance are you waiting to change before you'll let yourself be content?", "Philippians 4:10–13"],
  close: "Rejoice in the Lord, whatever today holds (4:4). Turn your worries into prayers with thanks (4:6). And thank God that He'll finish the good work He started in you (1:6)."
});

BQ.book({
  id: "colossians",
  title: "Jesus Over Everything",
  overview: "The church in Colossae was being pulled toward a mix of human philosophy, strict rules and special spiritual experiences that made Jesus seem like just one part of the picture. Paul answers with one of the highest views of Jesus in the Bible: He is the image of the invisible God, Creator of everything, head of the church, and all the fullness of God lives in Him. Since believers are complete in Him, they should set their hearts on things above and live new lives.",
  key: ["Colossians 1:15–16", "He is the image of the invisible God, the firstborn over all creation. Through Him all things were created, in heaven and on earth."],
  cast: [
    ["Paul", "Person", "1:1; 4:18", "Writing from prison to a church he had never visited."],
    ["Epaphras", "Person", "1:7; 4:12", "Started the church in Colossae and kept praying hard for them."],
    ["Onesimus", "Person", "4:9", "A runaway slave who became a faithful brother. He traveled with this letter.", "Philemon 1:10"],
    ["Luke", "Person", "4:14", "“Our dear friend Luke, the doctor,” who was with Paul."],
    ["Colossae", "Place", "1:2", "A small town in what is now Turkey, near Laodicea."]
  ],
  pray: "Take a slow breath. Colossians says Jesus holds all things together. Ask Him to hold together whatever feels like it's falling apart in your life (Colossians 1:17).",
  sections: [
    [1, 1, "Who Jesus Is", "Jesus is the image of God, the Creator, head of the church, and the one who makes peace."],
    [2, 2, "Complete in Christ", "Don't be taken captive by empty philosophy or rules. You're complete in Him."],
    [3, 4, "New Life", "Set your heart on things above, put on love, and do everything in the name of Jesus."]
  ],
  qs: [
    { r: 1, ref: "Colossians 1:15", ch: [1], q: "Colossians 1:15 says Jesus is the image of the ____ God.", o: ["invisible", "angry", "distant", "unknown"], why: "If you want to know what God is like, look at Jesus." },
    { r: 1, ref: "Colossians 1:16–17", ch: [1], q: "What does Colossians 1:17 say Jesus does for all things?", o: ["Holds them together", "Ignores them", "Destroys them", "Counts them"], why: "Everything was created through Him and for Him, and He keeps it all going." },
    { r: 1, ref: "Colossians 3:2", ch: [3], q: "Colossians 3:2 tells believers to set their minds on what?", o: ["Things above", "Earthly things", "Their enemies", "Their past"], why: "Your life is now hidden with Christ in God. Live from that." },
    { r: 1, ref: "Colossians 1:7; 2:1", ch: [1, 2], q: "True or false: Paul had personally started the church in Colossae and visited it often.", tf: false, why: "Epaphras started it (1:7). Many of them had never met Paul face to face (2:1), but he cared deeply for them." },
    { r: 1, ref: "Colossians 3:12–14", ch: [3], q: "In Colossians 3, what does Paul say to put on over all the other virtues?", o: ["Love", "Pride", "Wealth", "Strictness"], why: "Love binds all the others together in perfect unity (3:14)." },
    { r: 2, ref: "Colossians 2:8", ch: [2], q: "What does Colossians 2:8 warn against?", o: ["Empty philosophy built on human ideas", "Reading too much of the Old Testament", "Spending too much time praying", "Giving too much help to the poor"], why: "Ideas that leave Jesus out, or push Him to the side, are empty, no matter how smart they sound." },
    { r: 2, ref: "Colossians 2:9–10", ch: [2], q: "Colossians 2:9 says all the fullness of God lives in Christ in bodily form. What does that mean for believers?", o: ["They are complete in Him and need nothing more", "They must add secret knowledge to be saved", "They should worship angels too", "They need special diets to reach God"], why: "You don't need Jesus-plus-something. In Him you have everything (2:10)." },
    { r: 2, ref: "Colossians 3:17", ch: [3], q: "What does Colossians 3:17 say to do in the name of the Lord Jesus?", o: ["Whatever you do, in word or deed", "Only your prayers at church", "Only your work for the church", "Only the big decisions in life"], why: "Every part of life, giving thanks to God the Father through Him." },
    { r: 2, ref: "Colossians 3:23", ch: [3], q: "Colossians 3:23 says to work at whatever you do with all your heart, as working for whom?", o: ["The Lord, not people", "Only your boss at work","Yourself and your future", "The money at the end"], why: "Even ordinary jobs become worship when you do them for Jesus." },
    { r: 3, ref: "Colossians 1:16 · John 1:3", ch: [1], look: ["John 1:1–3", "Hebrews 1:2"], q: "Paul says all things were created through Jesus. Which Gospel says the same thing in its first chapter?", o: ["John", "Mark", "Luke", "Matthew"], why: "“Through him all things were made; without him nothing was made that has been made” (John 1:3)." },
    { r: 3, ref: "Colossians 2:13–15", ch: [2], look: ["Colossians 2:13–15"], art: "cross", q: "Colossians 2:14 says God canceled the record of debt against us. What did He do with it?", o: ["Nailed it to the cross", "Gave it to the priests", "Hid it in the temple", "Sent it to Rome"], why: "Jesus paid it in full. And at the cross He disarmed the powers of evil and triumphed over them." },
    { r: 3, ref: "Colossians 1:20 · Romans 5:10", ch: [1], look: ["Romans 5:10", "2 Corinthians 5:18"], q: "Colossians 1:20 says God reconciled all things to Himself through Christ. How?", o: ["Through His blood on the cross", "By simply ignoring sin", "By giving a new set of laws", "By sending more prophets"], why: "The cross is how God brings broken things back together, starting with us." }
  ],
  words: [
    ["Image", "Colossians 1:15", "A perfect likeness. Jesus shows exactly what the invisible God is like."],
    ["Firstborn", "Colossians 1:15", "Not the first one created, but first in rank and honor over all creation."],
    ["Fullness", "Colossians 2:9", "All of who God is. It lives in Jesus completely."],
    ["Reconcile", "Colossians 1:20", "To restore a broken relationship and bring peace."],
    ["Philosophy", "Colossians 2:8", "A system of human ideas about life. Paul warns about ones that leave Christ out."]
  ],
  under: [
    ["Colossians 1:17", "In Him all things hold together.", "Jesus isn't just part of your life. He holds it all together.", "When things feel like they're falling apart, pray this verse."],
    ["Colossians 3:2", "Set your minds on things above.", "What you think about shapes how you live.", "Each morning this week, think about one thing above before your day starts."],
    ["Colossians 3:13", "Forgive as the Lord forgave you.", "God's forgiveness is both our model and our motivation.", "Forgive one small offense this week right away, before it grows."],
    ["Colossians 3:23", "Work as for the Lord.", "Ordinary work becomes worship when it's done for Jesus.", "Do your next chore or job task as if Jesus were the one you're serving."]
  ],
  reflect: ["The Colossians were tempted to add things to Jesus, like rules, philosophy or special experiences (Colossians 2:8–10). What are you tempted to add to Jesus to feel complete?", "Colossians 2:6–10"],
  close: "Worship Jesus, who holds all things together (1:17). Thank Him for nailing your debt to the cross (2:14). And set your heart on things above as you go about your work today (3:2, 23)."
});
